package vault

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	vaultDir    = "/var/lib/securevault/data"
	tempDir     = "/var/lib/securevault/tmp"
	maxKeyLen   = 64
	maxValueLen = 4096
)

type SecureVault struct {
	mu        sync.RWMutex
	masterKey [32]byte
	nonceSize int
	gcm       cipher.AEAD
}

func NewSecureVault(passphrase string) (*SecureVault, error) {
	v := &SecureVault{}
	v.masterKey = sha256.Sum256([]byte(passphrase))

	block, err := aes.NewCipher(v.masterKey[:])
	if err != nil {
		return nil, fmt.Errorf("cipher init: %w", err)
	}

	v.gcm, err = cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("gcm init: %w", err)
	}
	v.nonceSize = v.gcm.NonceSize()

	if err := os.MkdirAll(vaultDir, 0700); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(tempDir, 0700); err != nil {
		return nil, err
	}
	return v, nil
}

func (v *SecureVault) sanitizeKey(key string) (string, error) {
	if len(key) == 0 || len(key) > maxKeyLen {
		return "", fmt.Errorf("invalid key length")
	}
	for _, c := range key {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
			return "", fmt.Errorf("invalid character in key: %c", c)
		}
	}
	return key, nil
}

func (v *SecureVault) resolveStoragePath(key string) (string, error) {
	sanitized, err := v.sanitizeKey(key)
	if err != nil {
		return "", err
	}
	hashed := sha256.Sum256([]byte(sanitized))
	filename := hex.EncodeToString(hashed[:16])
	fullPath := filepath.Join(vaultDir, filename+".enc")

	// Verify the resolved path is within vault directory
	resolved, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}
	if !strings.HasPrefix(resolved, vaultDir) {
		return "", fmt.Errorf("path traversal detected")
	}
	return resolved, nil
}

func (v *SecureVault) encrypt(plaintext []byte) ([]byte, error) {
	nonce := make([]byte, v.nonceSize)
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return v.gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (v *SecureVault) decrypt(ciphertext []byte) ([]byte, error) {
	if len(ciphertext) < v.nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ct := ciphertext[:v.nonceSize], ciphertext[v.nonceSize:]
	return v.gcm.Open(nil, nonce, ct, nil)
}

func (v *SecureVault) atomicWrite(destPath string, data []byte) error {
	// Create temp file in temp directory
	tmpFile, err := os.CreateTemp(tempDir, "vault-*.tmp")
	if err != nil {
		return fmt.Errorf("create temp: %w", err)
	}
	tmpPath := tmpFile.Name()

	defer func() {
		if err != nil {
			os.Remove(tmpPath)
		}
	}()

	if _, err = tmpFile.Write(data); err != nil {
		tmpFile.Close()
		return fmt.Errorf("write temp: %w", err)
	}
	if err = tmpFile.Sync(); err != nil {
		tmpFile.Close()
		return fmt.Errorf("sync temp: %w", err)
	}
	tmpFile.Close()

	if err = os.Chmod(tmpPath, 0600); err != nil {
		return fmt.Errorf("chmod: %w", err)
	}

	// Rename to final destination - this is atomic on most filesystems
	if err = os.Rename(tmpPath, destPath); err != nil {
		return fmt.Errorf("rename: %w", err)
	}
	return nil
}

func (v *SecureVault) Store(key string, value []byte) error {
	v.mu.Lock()
	defer v.mu.Unlock()

	if len(value) > maxValueLen {
		return fmt.Errorf("value too large")
	}

	destPath, err := v.resolveStoragePath(key)
	if err != nil {
		return err
	}

	encrypted, err := v.encrypt(value)
	if err != nil {
		return fmt.Errorf("encrypt: %w", err)
	}

	return v.atomicWrite(destPath, encrypted)
}

func (v *SecureVault) Retrieve(key string) ([]byte, error) {
	v.mu.RLock()
	defer v.mu.RUnlock()

	storagePath, err := v.resolveStoragePath(key)
	if err != nil {
		return nil, err
	}

	data, err := os.ReadFile(storagePath)
	if err != nil {
		return nil, fmt.Errorf("read: %w", err)
	}

	return v.decrypt(data)
}

func (v *SecureVault) Delete(key string) error {
	v.mu.Lock()
	defer v.mu.Unlock()

	storagePath, err := v.resolveStoragePath(key)
	if err != nil {
		return err
	}

	return os.Remove(storagePath)
}
